-- =============================================================================
-- PALLIKKAL MEDICALS · version 80 · FINAL CHECK (read-only)
-- Run AFTER 0037, 0038 and 0039_day_close_print_purchase_no.sql in the Supabase SQL editor.
-- It changes nothing. Copy the whole result grid (all rows) and send it back.
-- Every row should show ok = true. "detail" explains what was found.
-- =============================================================================
WITH
rpc AS (SELECT unnest(ARRAY['adjust_stock','audit_list','audit_log_export','audit_login_history','audit_overview','audit_settings_get','audit_settings_save','audit_user_report','billing_allocate','billing_log_event','billing_my_config','billing_release','billing_touch','cash_book','complete_password_change','confirm_purchase_v2','confirm_purchase_v3','correct_daily_cash_opening','customer_dues','customer_outstanding','customer_stats','delete_medicine_image','delivery_assign','delivery_management_list','delivery_management_list_v2','delivery_my_jobs','delivery_my_jobs_v2','delivery_presence_my_status','delivery_presence_summary','delivery_report_issue','delivery_set_details','delivery_set_presence','delivery_set_request','delivery_settings_set','delivery_update_status','delivery_update_status_v2','document_activity','document_categories','document_category_save','document_folder_delete','document_folder_save','document_log_access','document_move','document_register','document_reminders_save','document_remove','document_renew','document_restore','document_settings_save','document_update','document_versions','documents_list','documents_overview','end_work_session','expense_cancel','expense_category_add','expense_category_deactivate','expense_category_get_list','expense_category_reactivate','expense_category_rename','expense_get_detail','expense_get_list','expense_get_summary','expense_post','expense_register_receipt','expense_save_draft','expiry_return_candidates','finalize_sale_v3','finance_balances','finance_monthly','finance_overview','finance_transactions','get_branch_profile','get_daily_cash_opening','inventory_valuation','invoice_detail','invoice_lookup','invoice_search','invoice_share_link','invoice_view_info','ledger_summary','low_stock','medicine_deactivation_request_list','my_role','my_shop_open_status','opening_stock_edit_submitted_batch','opening_stock_get_draft','opening_stock_save_draft','opening_stock_set_batch_gst','opening_stock_submit','payable_balances','physical_count','process_purchase_return','process_purchase_return_v2','process_sales_return','process_sales_return_v2','public_invoice','public_medicine_search','public_shop_is_open','public_site_info','purchase_detail','purchase_document_list','purchase_draft_delete','purchase_draft_list','purchase_draft_save','purchase_history','purchase_invoice_exists','purchase_list','purchase_list_v2','purchase_order_cancel','purchase_order_list','purchase_order_save','purchase_return_list','purchase_returnable','record_account_opening','record_customer_receipt','record_daily_cash_opening','record_party_opening_balance','record_supplier_payment','register_medicine_image','register_purchase_document','remove_purchase_document','report_period_summary','report_pnl','report_run_delete','report_run_log','report_runs_list','reports_overview','reports_sales_by_category','request_medicine_deactivation','return_detail','returnable_items','returns_base_total','returns_top_medicines','reverse_account_opening','reverse_party_opening_balance','review_medicine_deactivation','sales_daily','sales_list','sales_summary','sales_top_medicines','save_branch_profile','set_batch_stock_status','set_credit_limit','set_primary_image','set_quarantine','set_shop_open_status','settings_backup_export','settings_backup_list','settings_get','settings_reset','settings_restore','settings_save','settings_save_billing','settings_save_branding','settings_system_info','staff_activities','staff_attendance_day','staff_attendance_register','staff_attendance_save','staff_attendance_trend','staff_leave_decide','staff_leave_save','staff_leaves_list','staff_list','staff_login_history','staff_overview','staff_performance','staff_roles_permissions','staff_set_active','staff_set_role','staff_update','start_work_session','stock_transfer','stock_transfer_branches','touch_work_session','website_settings_get','website_settings_save','whatsapp_activity','whatsapp_bills','whatsapp_campaign_create','whatsapp_campaign_queue','whatsapp_campaign_status','whatsapp_campaigns_list','whatsapp_conversations','whatsapp_due_customers','whatsapp_invoice_link_revoke','whatsapp_log_reply','whatsapp_mark','whatsapp_overview','whatsapp_queue_invoice','whatsapp_queue_message','whatsapp_refill_candidates','whatsapp_settings_get','whatsapp_settings_save','whatsapp_template_delete','whatsapp_template_save','whatsapp_templates_list','whatsapp_thread','invoices_for_day','record_daily_cash_closing','get_daily_cash_closing','correct_daily_cash_closing','cash_closing_list','next_purchase_no']) AS name),
rpc_missing AS (SELECT string_agg(r.name, ', ' ORDER BY r.name) m, count(*) c FROM rpc r
  WHERE NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname = r.name)),
rpc_noexec AS (SELECT string_agg(DISTINCT p.proname, ', ') m, count(DISTINCT p.proname) c FROM rpc r JOIN pg_proc p ON p.proname = r.name JOIN pg_namespace n ON n.oid = p.pronamespace AND n.nspname = 'public'
  WHERE NOT has_function_privilege('authenticated', p.oid, 'EXECUTE')
    AND NOT EXISTS (SELECT 1 FROM pg_proc p2 JOIN pg_namespace n2 ON n2.oid = p2.pronamespace AND n2.nspname = 'public' WHERE p2.proname = r.name AND has_function_privilege('authenticated', p2.oid, 'EXECUTE'))),
tbl AS (SELECT unnest(ARRAY['account_opening_balances','audit_logs','billing_settings','branches','categories','customer_doctor_sheets','customer_receipts','customers','daily_cash_openings','distributors','financial_ledger','held_bills','login_attempts','manufacturers','medicine_batches','medicine_images','medicines','party_opening_balances','payments','profiles','purchase_invoices','purchase_items','purchase_returns','sales_invoices','sales_return_items','sales_returns','stock_movements','stock_transfers','supplier_payments','unit_conversions','work_sessions','daily_invoice_counters','opening_stock_sessions','opening_stock_items','whatsapp_messages','pharmacy_settings','daily_cash_closings','purchase_no_counters']) AS name),
tbl_missing AS (SELECT string_agg(t.name, ', ') m, count(*) c FROM tbl t WHERE to_regclass('public.' || t.name) IS NULL),
rls_off AS (SELECT string_agg(c.relname, ', ') m, count(*) c FROM tbl t JOIN pg_class c ON c.relname = t.name JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public'
  WHERE c.relkind = 'r' AND NOT c.relrowsecurity),
src AS (SELECT p.proname, p.prosrc FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public'),
br AS (SELECT * FROM public.branches WHERE is_active ORDER BY code, id LIMIT 1),
web AS (SELECT s.value v FROM public.pharmacy_settings s JOIN br ON br.id = s.branch_id WHERE s.key = 'website'),
today AS (SELECT (now() AT TIME ZONE 'Asia/Kolkata')::date d)
SELECT * FROM (
          SELECT 01 AS n, 'All database functions used by the pages exist' AS check_name, (SELECT c FROM rpc_missing) = 0 AS ok, coalesce('missing: ' || (SELECT m FROM rpc_missing), (SELECT count(*) FROM rpc)::text || ' functions found') AS detail
UNION ALL SELECT 02, 'Signed-in users may call them', (SELECT c FROM rpc_noexec) = 0, coalesce('no EXECUTE: ' || (SELECT m FROM rpc_noexec), 'ok')
UNION ALL SELECT 03, 'All tables used by the pages exist', (SELECT c FROM tbl_missing) = 0, coalesce('missing: ' || (SELECT m FROM tbl_missing), (SELECT count(*) FROM tbl)::text || ' tables found')
UNION ALL SELECT 04, 'Row-level security is ON for those tables', (SELECT c FROM rls_off) = 0, coalesce('RLS off: ' || (SELECT m FROM rls_off), 'ok')
UNION ALL SELECT 05, '0037 · pharmacy contact on bills', (SELECT phone = '8848642677' AND email = 'pallikkalpharmacy@gmail.com' AND address ILIKE 'Pallikkal Bazar%' AND pincode = '673634' FROM br), (SELECT concat_ws(' · ', phone, email, address, city, pincode) FROM br)
UNION ALL SELECT 06, '0037 · home page: Ayurvedic phone 9895843039', coalesce((SELECT v->'ayurveda'->>'phone' = '9895843039' FROM web), false), coalesce((SELECT v->'ayurveda'->>'phone' || ' · WhatsApp ' || coalesce(v->>'whatsapp','') FROM web), 'website settings row not found')
UNION ALL SELECT 07, '0037 · sessions last all day (only earlier days closed)', EXISTS (SELECT 1 FROM src WHERE proname = 'start_work_session' AND prosrc ILIKE '%work_date < v_today%'), 'start_work_session'
UNION ALL SELECT 08, '0037 · bill number YYYY-MM-DD-#### (4 digits)', EXISTS (SELECT 1 FROM src WHERE proname = 'assign_daily_invoice_number' AND prosrc ILIKE '%lpad(v_number::text, 4%')
                 AND EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_assign_daily_invoice_number' AND NOT tgisinternal), coalesce((SELECT 'latest bill: ' || invoice_no FROM public.sales_invoices ORDER BY created_at DESC LIMIT 1), 'no bills yet')
UNION ALL SELECT 09, '0037 · medicine discount ₹ amount column', EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'medicines' AND column_name = 'discount_amount'), 'medicines.discount_amount'
UNION ALL SELECT 29, '0037 · pages may read/write the discount column', has_column_privilege('authenticated', 'public.medicines', 'discount_amount', 'SELECT') AND has_column_privilege('authenticated', 'public.medicines', 'discount_amount', 'UPDATE') AND has_column_privilege('authenticated', 'public.medicine_batches', 'distributor_id', 'SELECT'), 'column grants for medicines.discount_amount, medicine_batches.distributor_id'
UNION ALL SELECT 30, '0038 · billing uses the medicine % / ₹ discount', (SELECT count(*) FROM src WHERE proname IN ('_billing_fefo_compute','finalize_sale_v3') AND prosrc LIKE '%billing_medicine_discount_pct%') >= 2 AND public.billing_medicine_discount_pct(0, 5, 50, 50, 50) = 10, 'run 0038_billing_medicine_discount.sql if false'
UNION ALL SELECT 31, '0039 · closing balance: one per day', EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.daily_cash_closings'::regclass AND contype = 'u'), (SELECT count(*) FROM public.daily_cash_closings)::text || ' closing balance(s) recorded'
UNION ALL SELECT 32, '0039 · purchase order numbers 1, 2, 3 …', EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_assign_purchase_no' AND NOT tgisinternal) AND (SELECT count(*) FROM public.purchase_invoices WHERE purchase_no IS NULL) = 0, 'last number: ' || COALESCE((SELECT max(purchase_no)::text FROM public.purchase_invoices), 'none yet')
UNION ALL SELECT 33, '0039 · QR code option in Print & Invoice settings', public._settings_defaults()->'invoice' ? 'qr_mode', COALESCE((SELECT value->>'qr_mode' FROM public.pharmacy_settings s JOIN br ON br.id = s.branch_id WHERE s.key = 'invoice'), 'whatsapp (default)')
UNION ALL SELECT 34, 'Drug licence numbers on bills (info)', true, COALESCE((SELECT array_to_string(ARRAY(SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(drug_licence_nos) = 'array' THEN drug_licence_nos ELSE '[]'::jsonb END)), ', ') FROM br), '') || ' · GSTIN ' || COALESCE((SELECT gstin FROM br), 'not set')
UNION ALL SELECT 35, '0039 · opening balances accept today (India time) after midnight', NOT EXISTS (SELECT 1 FROM src WHERE proname = 'record_party_opening_balance' AND prosrc ~* 'p_as_of_date\s*>\s*CURRENT_DATE'), 'record_party_opening_balance'
UNION ALL SELECT 10, '0037 · discount rule: ₹5 off a ₹50 unit = 10%', public.billing_medicine_discount_pct(NULL, 5, 50, 50, 50) = 10, public.billing_medicine_discount_pct(NULL, 5, 50, 50, 50)::text
UNION ALL SELECT 11, '0037 · medicine GST may be 0 (default 0)', (SELECT column_default FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'medicines' AND column_name = 'tax_rate') = '0', (SELECT 'default ' || coalesce(column_default, 'none') FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'medicines' AND column_name = 'tax_rate')
UNION ALL SELECT 12, '0037 · MRP includes GST on every batch', (SELECT count(*) FROM public.medicine_batches WHERE price_includes_tax = false) = 0, (SELECT count(*) FROM public.medicine_batches WHERE price_includes_tax = false)::text || ' batch(es) with GST added on top'
UNION ALL SELECT 13, '0037 · initial stock: GST % and distributor columns', (SELECT count(*) FROM information_schema.columns WHERE table_schema = 'public' AND ((table_name = 'opening_stock_items' AND column_name IN ('tax_rate','distributor_id')) OR (table_name = 'medicine_batches' AND column_name = 'distributor_id'))) = 3, 'opening_stock_items.tax_rate / distributor_id, medicine_batches.distributor_id'
UNION ALL SELECT 14, '0037 · WhatsApp: every staff role can send', EXISTS (SELECT 1 FROM src WHERE proname = '_wa_guard' AND prosrc ILIKE '%inventory_staff%'), '_wa_guard'
UNION ALL SELECT 15, '0037 · staff parity: billing engine', EXISTS (SELECT 1 FROM src WHERE proname = '_billing_assert_staff' AND prosrc ILIKE '%inventory_staff%') AND EXISTS (SELECT 1 FROM src WHERE proname = 'finalize_sale_v3' AND prosrc ILIKE '%_billing_assert_staff%'), 'billing staff check (_billing_assert_staff) used by finalize_sale_v3'
UNION ALL SELECT 16, '0037 · staff parity: returns, customers, delivery, inventory', (SELECT count(*) FROM src WHERE proname IN ('_returns_guard','customer_outstanding','delivery_assign','adjust_stock','set_shop_open_status') AND prosrc ILIKE '%inventory_staff%') = 5, 'guards include every staff role'
UNION ALL SELECT 17, '0037 · staff cannot see total income', EXISTS (SELECT 1 FROM src WHERE proname = 'sales_summary' AND prosrc ~* 'super_admin') , 'sales_summary is Admin-only'
UNION ALL SELECT 18, 'Visitors (not signed in) cannot call billing', NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace AND n.nspname = 'public' WHERE p.proname IN ('finalize_sale_v3','confirm_purchase_v2','record_daily_cash_opening') AND has_function_privilege('anon', p.oid, 'EXECUTE')), 'billing, purchases and cash opening need a login'
UNION ALL SELECT 19, 'Home page: open/closed status readable by visitors', EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace AND n.nspname = 'public' WHERE p.proname IN ('public_site_info','public_shop_is_open') AND has_function_privilege('anon', p.oid, 'EXECUTE')), 'public website function callable by anon'
UNION ALL SELECT 20, 'Every active user has a branch', (SELECT count(*) FROM public.profiles WHERE is_active AND branch_id IS NULL) = 0, (SELECT count(*) FROM public.profiles WHERE is_active AND branch_id IS NULL)::text || ' active user(s) without branch'
UNION ALL SELECT 21, 'Active users by role (info)', true, (SELECT string_agg(role || ': ' || c, ', ' ORDER BY role) FROM (SELECT coalesce(r.code, 'no role') AS role, count(*) c FROM public.profiles p LEFT JOIN public.roles r ON r.id = p.role_id WHERE p.is_active GROUP BY 1) x)
UNION ALL SELECT 22, 'Users who must change password (info)', true, (SELECT count(*) FROM public.profiles WHERE is_active AND must_change_password)::text
UNION ALL SELECT 23, 'No stock below zero', (SELECT count(*) FROM public.medicine_batches WHERE qty < 0) = 0, (SELECT count(*) FROM public.medicine_batches WHERE qty < 0)::text || ' batch(es) negative'
UNION ALL SELECT 24, 'Medicines / batches / distributors (info)', true, (SELECT count(*) FROM public.medicines)::text || ' medicines · ' || (SELECT count(*) FROM public.medicine_batches)::text || ' batches · ' || (SELECT count(*) FROM public.distributors)::text || ' distributors'
UNION ALL SELECT 25, 'Today''s opening balance entries (info)', true, (SELECT count(*) FROM public.daily_cash_openings, today WHERE opening_date = today.d)::text || ' today · ' || (SELECT count(*) FROM public.daily_cash_openings)::text || ' in total'
UNION ALL SELECT 26, 'Sessions left open from earlier days (closed at next login)', true, (SELECT count(*) FROM public.work_sessions, today WHERE logout_at IS NULL AND work_date < today.d)::text
UNION ALL SELECT 27, 'Bills today (info)', true, (SELECT count(*) FROM public.sales_invoices, today WHERE (created_at AT TIME ZONE 'Asia/Kolkata')::date = today.d)::text
UNION ALL SELECT 28, 'Storage buckets for logos / documents / images', (SELECT count(*) FROM storage.buckets) >= 1, (SELECT string_agg(id, ', ') FROM storage.buckets)
) checks ORDER BY n;
